    image_patch = ImagePatch(image)
    people_patches = image_patch.find("person")
    numbers_patches = image_patch.find("number")

    if not people_patches or not numbers_patches:
        return image_patch

    people_centers = [(p.left + p.right) / 2 for p in people_patches]
    numbers_centers = [(p.left + p.right) / 2 for p in numbers_patches]

    min_distance = float('inf')
    closest_person = None

    for person_center in people_centers:
        for number_center in numbers_centers:
            distance = abs(person_center - number_center)
            if distance < min_distance:
                min_distance = distance
                closest_person = next(p for p in people_patches if (p.left + p.right) / 2 == person_center)

    if closest_person:
        people_patches.remove(closest_person)

    return closest_person if closest_person else people_patches[0]

